"""Migration of the legacy CRMScript division-by-zero behavior."""

from __future__ import annotations

from typing import Any


def _coerce_numeric(value: Any) -> float:
    """Apply legacy numeric coercion for values used in arithmetic."""
    if value is None:
        return 0.0
    if isinstance(value, str):
        if value.strip() == "":
            return 0.0
        try:
            return float(value)
        except (TypeError, ValueError, OverflowError):
            return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy semantics, auditing division by zero."""
    numerator = _coerce_numeric(a)
    denominator = _coerce_numeric(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / denominator, []
    except (ArithmeticError, OverflowError):
        return 0.0, []
